public bool ContainsNearbyDuplicate(int[] nums, int k) {
    var last = new Dictionary<int, int>();   // value → last index to the left of i
    for (int i = 0; i < nums.Length; i++) {
        if (last.TryGetValue(nums[i], out int j) && i - j <= k)
            return true;                     // the same number at most k back
        last[nums[i]] = i;                   // invariant: now the last one is i
    }
    return false;
}

