// O(min(n, k)) memory: only the last k numbers are in the window
var window = new HashSet<int>();
for (int i = 0; i < nums.Length; i++) {
    if (!window.Add(nums[i])) return true;              // the same number is in the window
    if (window.Count > k) window.Remove(nums[i - k]);   // the oldest one goes
}
return false;

